@ .buttons-main
{
	margin-top: 4px;
	width: 100%;
	display: flex;
	justify-content: center;
	flex-wrap: wrap;
}

.synergyLogoContainer {
	position: relative;
	display: inline-block;
	border-bottom: 1px dotted #F1AE00;
	vertical-align: middle;
}

.synergyLogoContainer span {
	vertical-align: middle;
}

.synergyLogoContainer img {
	height: 16px;
	margin-top: 4px;
}

.synergyLogoContainer .text {
	visibility: hidden;
	background-color: #F1AE00;
	color: #fff;
	text-align: center;
	padding: 5px 5px;
	border-radius: 6px;
	position: absolute;
	margin-left: 10px;
	z-index: 1;
}

.synergyLogoContainer .text::after {
	content: " ";
	position: absolute;
	top: 50%;
	right: 100%;
	/* To the left of the tooltip */
	margin-top: -5px;
	border-width: 5px;
	border-style: solid;
	border-color: transparent #F1AE00 transparent transparent;
}

.synergyLogoContainer:hover .text {
	visibility: visible;
}

