.summary-container {
	display: flex;
	flex-direction: column;
}

.button-summary-container, .text-summary-container {
	width: 100%;
	box-sizing: border-box;
}

.text-summary-container {
	display: flex;
    overflow: auto;
    padding: 10px;
	white-space: pre-wrap;
	word-break: break-word;
}

.button-summary {
	display: inline-flex;
    align-items: center;
	position: relative;
	padding-left: 10px;
    padding-right: 10px;
}

.button-summary img {
	padding-right: 5px;
}

.button-summary-tooltip {
	visibility: hidden;
	background-color: #F1AE00;
	color: #fff;
	text-align: center;
	padding: 5px 5px;
	border-radius: 6px;
	position: absolute;
	left: 105%;
	z-index: 1;
}

.button-summary-tooltip::after {
	content: " ";
	position: absolute;
	top: 50%;
	right: 100%;
	margin-top: -5px;
	border-width: 5px;
	border-style: solid;
	border-color: transparent #F1AE00 transparent transparent;
}

.button-summary:hover .button-summary-tooltip {
	visibility: visible;
}

.text-summary {
	padding: 10px;
    border: 1.5px dashed #F1AE00;
    border-radius: 8px;
}

.text-summary-hidden {
	display: none;
}

.text-summary-show {
	display: flex;
}
